// Kotlin port of the Tremor Witness repo's packages/core/src/quorum.ts and registry.ts. Must stay bit-identical:
// app/src/test/resources/golden/core-v1.json is generated by running the TypeScript originals (tools/golden).
package dev.dhruv.twmesh.core

data class Trigger(
    val id: String,          // unique id. Mesh messages use lowercase hex, so ordering matches JS localeCompare.
    val sensor: String,      // ENS label of the phone
    val creator: String,     // address that signed it
    val tMs: Long,           // phone's claimed wall-clock time
    val ppvMmS: Double,
    val fDomHz: Double,
    val label: String,       // "structural" | "handling"
    val createdAtMs: Long? = null, // when it was recorded (Arkiv) / first heard (mesh)
)

data class QuorumParams(
    val k: Int,
    val windowMs: Long,
    val isLive: ((Trigger) -> Boolean)? = null,
)

enum class RejectReason(val js: String) { HANDLING("handling"), NOT_REGISTERED("not-registered"), NO_QUORUM("no-quorum") }

data class ConfirmedEvent(val tMs: Long, val sensors: List<String>, val members: List<Trigger>, val ppvMinMmS: Double, val ppvMaxMmS: Double)
data class QuorumResult(val events: List<ConfirmedEvent>, val rejected: List<Pair<Trigger, RejectReason>>)

object Quorum {
    fun compute(triggers: List<Trigger>, p: QuorumParams): QuorumResult {
        val rejected = ArrayList<Pair<Trigger, RejectReason>>()
        val valid = ArrayList<Trigger>()
        for (t in triggers) when {
            p.isLive != null && !p.isLive.invoke(t) -> rejected += t to RejectReason.NOT_REGISTERED
            t.label != "structural" -> rejected += t to RejectReason.HANDLING
            else -> valid += t
        }
        valid.sortWith(compareBy<Trigger> { it.tMs }.thenBy { it.id })   // = (a.tMs - b.tMs || a.id.localeCompare(b.id)) for hex ids

        val used = HashSet<String>()
        val events = ArrayList<ConfirmedEvent>()
        for (i in valid.indices) {
            val anchor = valid[i]
            if (anchor.id in used) continue
            val bySensor = LinkedHashMap<String, Trigger>()
            var j = i
            while (j < valid.size && valid[j].tMs - anchor.tMs <= p.windowMs) {
                val c = valid[j]
                if (c.id !in used && c.sensor !in bySensor) bySensor[c.sensor] = c
                j++
            }
            if (bySensor.size >= p.k) {
                val members = bySensor.values.toList()
                members.forEach { used += it.id }
                j = i
                while (j < valid.size && valid[j].tMs - anchor.tMs <= p.windowMs) {
                    if (valid[j].sensor in bySensor) used += valid[j].id
                    j++
                }
                val ts = members.map { it.tMs }.sorted()
                events += ConfirmedEvent(
                    tMs = ts[ts.size / 2], sensors = members.map { it.sensor }.sorted(), members = members,
                    ppvMinMmS = members.minOf { it.ppvMmS }, ppvMaxMmS = members.maxOf { it.ppvMmS },
                )
            } else {
                used += anchor.id
                rejected += anchor to RejectReason.NO_QUORUM
            }
        }
        return QuorumResult(events, rejected)
    }
}

/** registry.ts: when a phone label belonged to an owner. toMs = min(unregistration, expiry); Long.MAX_VALUE if open. */
data class RegistrationInterval(val label: String, val owner: String, val fromMs: Long, val toMs: Long)

enum class AsOf(val js: String) {
    OK("ok"), NOT_REGISTERED_AT_READING("not-registered-at-reading-time"), NOT_REGISTERED_AT_UPLOAD("not-registered-at-upload-time"),
    CLAIMS_FUTURE("claims-future-time"), NO_UPLOAD_TIME("no-upload-time")
}

object Registry {
    fun registeredAt(intervals: List<RegistrationInterval>, label: String, owner: String, atMs: Long, slackBeforeMs: Long = 0): Boolean {
        val o = owner.lowercase()
        return intervals.any { it.label == label && it.owner.lowercase() == o && atMs >= it.fromMs - slackBeforeMs && atMs < it.toMs }
    }

    /**
     * T13 as-of rule. On the mesh, [Trigger.createdAtMs] is the time THIS phone first heard the message
     * (the sender can't choose it), playing the role Arkiv's recording time plays online.
     */
    fun asOfCheck(intervals: List<RegistrationInterval>, t: Trigger, futureSlackMs: Long = 120_000, joinSlackMs: Long = 120_000): AsOf {
        val created = t.createdAtMs ?: return AsOf.NO_UPLOAD_TIME
        if (t.tMs > created + futureSlackMs) return AsOf.CLAIMS_FUTURE
        if (!registeredAt(intervals, t.sensor, t.creator, t.tMs, joinSlackMs)) return AsOf.NOT_REGISTERED_AT_READING
        if (!registeredAt(intervals, t.sensor, t.creator, created, joinSlackMs)) return AsOf.NOT_REGISTERED_AT_UPLOAD
        return AsOf.OK
    }
}
